import asyncio, json, re
from app.scrapers.app_details import AppStoreAppScraper
from bs4 import BeautifulSoup

async def test\(\):
    s = AppStoreAppScraper\(\)
    html = await s._make_request\('https://apps.apple.com/us/app/id867374917'\)
    soup = BeautifulSoup\(html, 'html.parser'\)
    for script in soup.find_all\('script'\):
        src = script.string or ''
        if 'versionHistory' not in src:
            continue
        start = src.find\('{'\)
        data = json.loads\(src[start:]\)

        # Recursively find 'mostRecentVersion' key
        def find_key\(obj, key, depth=0\):
            if depth > 10: return None
            if isinstance\(obj, dict\):
                if key in obj:
                    return obj[key]
                for v in obj.values\(\):
                    r = find_key\(v, key, depth+1\)
                    if r is not None:
                        return r
            elif isinstance\(obj, list\):
                for item in obj:
                    r = find_key\(item, key, depth+1\)
                    if r is not None:
                        return r
            return None

        mrv = find_key\(data, 'mostRecentVersion'\)
        if mrv:
            print\('Found mostRecentVersion!'\)
            see_all = mrv.get\('seeAllAction', {}\)
            pd = see_all.get\('pageData', {}\)
            shelves = pd.get\('shelves', []\)
            print\('shelves count:', len\(shelves\)\)
            if shelves:
                items = shelves[0].get\('items', []\)
                print\(f'items: {len\(items\)}'\)
                for item in items[:3]:
                    print\(' v'+item.get\('primarySubtitle','?'\), '|', item.get\('secondarySubtitle','?'\)[:50]\)
        else:
            # Show top level structure
            print\('data keys:', list\(data.keys\(\)\)\)
            for entry in data.get\('data', []\):
                print\('  entry keys:', list\(entry.get\('data', {}\).keys\(\)\)[:10]\)
        break

asyncio.run\(test\(\)\)
